
import { defineComponent } from 'vue';

export default defineComponent({
  props: {
    modelValue: {
      type: String,
      default: '',
    },
    name: {
      type: String,
      required: true,
    },
    title: String,
    inlineHelp: String,
    type: {
      type: String,
      default: 'text',
    },
    maxlength: Number,
    autocomplete: {
      type: String,
      default: 'off',
    },
    autofocus: Boolean,
    fullWidth: Boolean,
  },
  emits: ['update:modelValue'],
  data() {
    return {
      hasFocus: false,
    };
  },
  mounted() {
    if (this.autofocus) {
      (this.$el.querySelector('input') as HTMLInputElement).focus();
    }
  },
});
